import { tags } from "typia";

/**
 * Aggregated monetary totals and counts for a computed cart summary.
 *
 * All monetary fields are expressed in the currency indicated by the parent
 * summary DTO.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallCartSummaryTotals = {
  /**
   * Total number of distinct cart lines currently included in the cart
   * summary.
   */
  itemCount: number & tags.Type<"int32"> & tags.Minimum<0>;

  /** Total quantity across all cart lines (sum of each line's quantity). */
  quantityTotal: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Total pre-discount merchandise amount across all cart lines (sum of
   * lineSubtotal values).
   */
  subtotal: number;

  /**
   * Total discount amount applied to the cart from all sources, including
   * line-level and cart-level promotions.
   */
  discountTotal?: number | null | undefined;

  /**
   * Estimated shipping fee for the current cart state and contextual
   * parameters supplied in the summary request, if an estimate can be
   * computed.
   */
  shippingEstimate?: number | null | undefined;

  /**
   * Estimated tax amount for the current cart state and contextual
   * parameters, if tax estimation is enabled and can be computed.
   */
  taxEstimate?: number | null | undefined;

  /**
   * Final estimated payable amount for the cart including merchandise,
   * discounts, shipping, and taxes as applicable.
   */
  grandTotal: number;
};
